import { useEffect, useState } from 'react';

type Command = { id: string; label: string; group: string; run: () => void };
export function CommandPalette({ commands, recent, onClose }: { commands: Command[]; recent: string[]; onClose: () => void }) {
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const visible = commands.filter(c => c.label.toLowerCase().includes(query.toLowerCase()));
  useEffect(() => setActive(0), [query]);
  const execute = (command: Command) => { command.run(); onClose(); };
  return <div className="palette-backdrop" onMouseDown={onClose}><section role="dialog" aria-modal="true" aria-label="Command palette" className="command-palette" onMouseDown={e => e.stopPropagation()}><input autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="Type a command" aria-label="Find a command" onKeyDown={e => { if(e.key === 'Escape') onClose(); if(e.key === 'ArrowDown') { e.preventDefault(); setActive(i => Math.min(i + 1, visible.length - 1)); } if(e.key === 'ArrowUp') { e.preventDefault(); setActive(i => Math.max(i - 1, 0)); } if(e.key === 'Enter' && visible[active]) execute(visible[active]); }} />{visible.length ? <div role="listbox" aria-label="Commands">{visible.map((command, index) => <button key={command.id} role="option" aria-selected={active === index} onMouseEnter={() => setActive(index)} onClick={() => execute(command)}><span>{command.label}</span><small>{command.group}</small></button>)}</div> : <p role="status">No commands match “{query}”.</p>}{!query && recent.length > 0 && <p className="recent">Recent: {recent.join(', ')}</p>}</section></div>;
}
